-- 0002_user_tokens.sql — Insight D1 schema (migration 0002).
--
-- D1 IS METADATA ONLY (INV-T5).
-- This database stores accounts, projects, config and access control.
-- It MUST NOT contain any telemetry data-point store (no per-reading rows,
-- no "readings" / "telemetry_points" / "samples" tables). Time-series
-- samples live in the analytics/data plane, never in D1.
--
-- Conventions (mirroring 0001_init.sql):
--   * ids            -> TEXT (ULID/UUID generated by the application)
--   * timestamps     -> INTEGER epoch milliseconds (Unix ms, UTC)
--   * booleans       -> INTEGER 0/1
--   * secret material-> stored as hashes only, never plaintext

-- ---------------------------------------------------------------------------
-- user_tokens — per-user API tokens (personal access tokens).
--
-- A user token authenticates a human's automation, NOT a device: it acts as
-- the owning user, carries one scope (`read` | `admin`) and is optionally
-- bound to a single project. The secret is stored ONLY as a hash, never in
-- plaintext — mirroring project_tokens.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS user_tokens (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL,
  name        TEXT NOT NULL,
  scope       TEXT NOT NULL DEFAULT 'read',
  project_id  TEXT,
  token_hash  TEXT NOT NULL,
  token_prefix TEXT,
  last_used_at INTEGER,
  expires_at  INTEGER,
  revoked_at  INTEGER,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_user_tokens_token_hash
  ON user_tokens (token_hash);

CREATE INDEX IF NOT EXISTS idx_user_tokens_user_id
  ON user_tokens (user_id);

CREATE INDEX IF NOT EXISTS idx_user_tokens_project_id
  ON user_tokens (project_id);

CREATE INDEX IF NOT EXISTS idx_user_tokens_expires_at
  ON user_tokens (expires_at);
